  if nxt->4 is distinct from cur.slides->4 then
    raise exception '389: slide 4 of When the screen goes to sleep should carry over unchanged and does not';
  end if;
  if nxt->8 is distinct from cur.slides->8 then
    raise exception '389: slide 8 of When the screen goes to sleep should carry over unchanged and does not';
  end if;
  if nxt->10 is distinct from cur.slides->10 then
    raise exception '389: slide 10 of When the screen goes to sleep should carry over unchanged and does not';
  end if;
  if cur.the_idea is distinct from $gc389$Little children do not end screen time, the ritual ends it for them. A gentle warning, a goodbye to the screen and a next thing to run to turn the hardest moment of the day into a routine.$gc389$ then
    raise exception '389: When the screen goes to sleep, the_idea has been edited since 7 November';
  end if;
  if cur.try_this is distinct from $gc389$Give a five minute whisper before the end, let your child wave goodbye to the screen, and have the next thing ready: a snack, a job, a game. The goodbye does the heavy lifting.$gc389$ then
    raise exception '389: When the screen goes to sleep, try_this has been edited since 7 November';
  end if;
  if cur.key_message is distinct from $gc389$Warn, wave goodbye, move on to the next thing.$gc389$ then
    raise exception '389: When the screen goes to sleep, key_message has been edited since 7 November';
  end if;
  update public.lessons
     set slides = nxt,
         the_idea = $gc389$Little children do not end screen time, the ritual ends it for them. A stopping place picked before it starts, a goodbye to the screen and a next thing to run to turn the hardest moment of the day into a routine.$gc389$,
         try_this = $gc389$Before the screen goes on, pick the stopping place together: one episode, then snack. When it ends, let your child wave goodbye and have the next thing ready. Tell them what comes next, not how long is left.$gc389$,
         key_message = $gc389$Pick the stopping place, wave goodbye, move on to the next thing.$gc389$
   where id = '3cc159b1-f3cd-46b9-9eb1-fc29c7899e40';
end $$;

-- ── Foundation: Big feelings and the screen, the opening recall ──────────
