   set slides = jsonb_set(slides, '{0,script}', to_jsonb($gc389$Recall: what do we do when the screen goes to sleep? A stopping place, a wave, a next thing. Today we talk about the feelings that sometimes arrive after the wave.$gc389$::text))
 where id = '158dee38-97ba-4b45-ae2b-55711a3cbf4e'
   and slides->0->>'script' = $gc389$Recall: what do we do when the screen goes to sleep? A whisper, a wave, a next thing. Today we talk about the feelings that sometimes arrive after the wave.$gc389$;

