  where l.module_id = 'ks2-04-screen-routines' and jsonb_typeof(x) = 'string'
  union all
  select x #>> '{}' as v from schools.school_lessons l, lateral jsonb_path_query(l.dsl_note, '$.**') as x
  where l.module_id = 'ks2-04-screen-routines' and jsonb_typeof(x) = 'string'
  union all
  select module_id from schools.school_lessons where module_id = 'ks2-04-screen-routines'
  union all
  select title from schools.school_lessons where module_id = 'ks2-04-screen-routines'
  union all
  select key_stage from schools.school_lessons where module_id = 'ks2-04-screen-routines'
  union all
